parameters.text:
=Generate exactly three distinct Milo story concept options from the input below.

Story ID: {{ $json.storyId }}
Raw idea: {{ $json.rawIdea }}
Theme: {{ $json.theme }}
Target length: {{ $json.targetLengthMinutes }} minutes
Age range: {{ $json.ageRange }}
Optional creative context:
Lesson: {{ $json.lesson }}
Setting: {{ $json.setting }}
Supporting characters: {{ $json.supportingCharacters }}
Notes: {{ $json.notes }}
Canon context:
The approved Milo canon context must be supplied to this generator from `MILO_CANON_CONTEXT.md`.

Use that canon context as authoritative creative constraints.
Do not invent facts that are absent from the supplied canon context.
Do not treat the optional creative context above as canon.
Requirements:
- Treat lesson, setting, supportingCharacters, and notes as optional creative direction. They are not canon and may be blank.
- Keep every concept suitable for the stated age range.
- Explore the supplied theme in a child-friendly way.
- Do not write a full outline or script.
- Return exactly the structure required by the connected output parser.
- supportingCharacters must contain only characters other than Milo; never include Milo in that array.

parameters.jsCode:
const items = $input.all();
const concepts = items.map(item => item.json);

const canonFiles = [
  'MILO_CHARACTER.md',
  'MILO_BACKSTORY.md',
  'VOICE_GUIDE.md',
  'VISUAL_REFERENCE.md',
  'PERSONALITY_RULES.md',
];

const valid =
  concepts.length === 3 &&
  concepts.every((c) => {
    const storyId = c.storyId ?? '';
    const conceptId = c.conceptId ?? '';

    return (
      /^MILO-[0-9]{3}$/.test(storyId) &&
      /^MILO-[0-9]{3}-C0[1-3]$/.test(conceptId) &&
      conceptId.startsWith(storyId + '-') &&
      ['title', 'premise', 'centralProblem', 'emotionalArc', 'lesson', 'setting'].every(
        field => typeof c[field] === 'string' && c[field].trim().length > 0
      ) &&
      Array.isArray(c.supportingCharacters) &&
      Array.isArray(c.canonReferences) &&
      c.canonReferences.length >= 1 &&
      c.canonReferences.every(file => canonFiles.includes(file)) &&
      c.approvalStatus === 'PENDING_REVIEW'
    );
  });

return [
  {
    json: {
      conceptBatchValid: valid,
      conceptCount: concepts.length,
      concepts,
    },
  },
];

const concepts = $input.first().json.concepts;

return concepts.map(concept => ({
  json: concept,
}));

const story = $json;
const canonVersion = String(story.canonVersion ?? '').trim();
const canonRef = String(story.canonRef ?? '').trim();
const canonLineageValid = /^canon-v[0-9]+\.[0-9]+$/.test(canonVersion) && /^[0-9a-f]{40}$/i.test(canonRef);

return {
  json: {
    ...story,
    canonVersion,
    canonRef,
    canonLineageValid,
    errorCode: canonLineageValid ? '' : 'CANON_LINEAGE_INVALID',
    message: canonLineageValid ? '' : 'Story canonVersion/canonRef is blank or invalid. Canon retrieval was not attempted.'
  }
};
